(()=>{const dialog=document.querySelector('.art-lightbox');let opener;function language(){const zh=document.documentElement.lang.startsWith('zh');document.querySelectorAll('[data-en][data-zh]').forEach(e=>e.textContent=e.dataset[zh?'zh':'en']);}document.addEventListener('portfolio:language',language);language();document.querySelectorAll('[data-art-time]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-art-time]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.querySelectorAll('.art-piece').forEach(f=>{const y=Number(f.dataset.year);f.hidden=b.dataset.artTime==='2017-2020'?y<2017:b.dataset.artTime==='2013-2016'?y>2016:false})}));document.querySelectorAll('.art-open').forEach(b=>b.addEventListener('click',()=>{opener=b;const im=b.querySelector('img');dialog.querySelector('img').src=im.src;dialog.querySelector('img').alt=im.alt;dialog.showModal()}));dialog.querySelector('button').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('close',()=>opener?.focus());})();